/**
 * The Prisme mark — the P at the wordmark's angle (+20°, top leans left),
 * Prisme's brand icon (docs/research/logo/recette-finale.md, "Favicon &
 * icônes d'app"). The SVG markup string here is
 * the single source for every rasterization: the favicon data URIs below and
 * the PNG icons generated by web/scripts/generate-icons.ts. The path is the
 * output of web/scripts/generate-brand-svg.py (exact Inter Extra Bold glyph
 * outline); keep the two in sync when the recipe changes.
 */

/** The mark as an SVG string in `color` (hex) — favicons and PNG icons
 * rasterize as-is, with no CSS, so the color is baked in. `pad` adds
 * breathing room around the glyph, as a fraction of the glyph height per
 * side (0 = the glyph fills the viewBox; favicons sit at ~0.18, matching
 * how other sites' icons breathe in a browser tab). */
export function prismeMarkSvg(color: string, pad = 0): string {
  const p = pad * 1490;
  const vb = `${-426.2 - p} ${-1490 - p} ${1379.2 + 2 * p} ${1490 + 2 * p}`;
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${vb}"><path fill="${color}" d="M116.2 0 -426.2 -1490H184.2Q352.1 -1490 497.4 -1425Q642.7 -1360 750.8 -1243.8Q859 -1127.7 914.6 -975Q970.5 -821.4 945.1 -707Q919.7 -592.5 818.7 -528.9Q717.7 -465.3 546.7 -465.3H168.3L66.8 -744H380.8Q463.8 -744 509.3 -773.1Q554.7 -802.2 564.2 -854.1Q573.6 -906 548.5 -975Q522.8 -1045.5 475.9 -1096.7Q428.9 -1148 362.6 -1175.8Q296.3 -1203.7 213 -1203.7H30.7L468.8 0Z"/></svg>`;
}

/** Favicon data URIs, one per theme (the media attribute on <link> makes the
 * browser pick — and live-swap — the right one). Colors match the --ink
 * tokens in global.css. Favicons must be self-contained URLs, hence the
 * data-URI wrapping. */
const URI = (svg: string): string =>
  `data:image/svg+xml,${encodeURIComponent(svg)}`;

export const PRISME_MARK_LIGHT = URI(prismeMarkSvg('#1b1b1f', 0.18));
export const PRISME_MARK_DARK = URI(prismeMarkSvg('#ededf0', 0.18));
